package fr.roadguard.app;
import android.media.MediaMetadata;import android.media.session.MediaController;import android.os.*;import android.view.*;import android.widget.*;
/** In-app draggable mini-player, no overlay permission or background service. */
final class MusicMapBubble extends LinearLayout {
 final MainActivity a;final Handler handler=new Handler(Looper.getMainLooper());final TextView title;final Button toggle;boolean attached;
 final Runnable refresh=new Runnable(){public void run(){if(!attached)return;MediaController c=MusicSources.current(a);MediaMetadata m=c==null?null:c.getMetadata();title.setText(m==null?MusicSources.label(a)+" · glisser ici":String.valueOf(m.getText(MediaMetadata.METADATA_KEY_TITLE)));toggle.setText(c!=null&&SpotifyControls.playing(c.getPlaybackState())?"Ⅱ":"▶");handler.postDelayed(this,1000);}};
 MusicMapBubble(MainActivity activity){super(activity);a=activity;setGravity(Gravity.CENTER_VERTICAL);setPadding(6,3,6,3);setBackground(a.bg(0xee14222c,24));title=new TextView(a);title.setTextColor(-1);title.setSingleLine(true);title.setEllipsize(android.text.TextUtils.TruncateAt.END);title.setTextSize(12);title.setPadding(8,4,8,4);addView(title,new LayoutParams(a.pxDp(100),a.pxDp(44)));
  button("◀","Piste précédente","previous");toggle=button("▶","Lecture / pause","toggle");button("▶|","Piste suivante","next");Button close=new Button(a);close.setText("×");close.setContentDescription("Masquer le mini lecteur");addView(close,new LayoutParams(a.pxDp(44),a.pxDp(44)));close.setOnClickListener(v->{a.getPreferences(0).edit().putBoolean("music_map_bubble",false).apply();((ViewGroup)getParent()).removeView(this);});
  float[] drag=new float[4];title.setOnTouchListener((v,e)->{switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:drag[0]=e.getRawX();drag[1]=e.getRawY();drag[2]=getX();drag[3]=getY();return true;case MotionEvent.ACTION_MOVE:View parent=(View)getParent();setX(Math.max(0,Math.min(parent.getWidth()-getWidth(),drag[2]+e.getRawX()-drag[0])));setY(Math.max(0,Math.min(parent.getHeight()-getHeight(),drag[3]+e.getRawY()-drag[1])));return true;case MotionEvent.ACTION_UP:a.getPreferences(0).edit().putFloat("music_bubble_x",getX()/Math.max(1,((View)getParent()).getWidth()-getWidth())).putFloat("music_bubble_y",getY()/Math.max(1,((View)getParent()).getHeight()-getHeight())).apply();return true;}return false;});
 }
 Button button(String glyph,String description,String command){Button b=new Button(a);b.setText(glyph);b.setContentDescription(description);b.setPadding(0,0,0,0);addView(b,new LayoutParams(a.pxDp(44),a.pxDp(44)));b.setOnClickListener(v->{if(!SpotifyControls.authorized(a))SpotifyControls.authorize(a);else if(!SpotifyControls.sendPlayer(MusicSources.current(a),command))Toast.makeText(a,"Démarre une lecture dans le lecteur choisi",Toast.LENGTH_SHORT).show();});return b;}
 protected void onAttachedToWindow(){super.onAttachedToWindow();attached=true;handler.post(refresh);post(()->{if(!attached||!(getParent() instanceof View))return;View parent=(View)getParent();setX(Math.max(0,parent.getWidth()-getWidth())*a.getPreferences(0).getFloat("music_bubble_x",.5f));setY(Math.max(0,parent.getHeight()-getHeight())*a.getPreferences(0).getFloat("music_bubble_y",.5f));});}
 protected void onDetachedFromWindow(){attached=false;handler.removeCallbacksAndMessages(null);super.onDetachedFromWindow();}
 static void add(MainActivity a){if(a.map==null||!a.getPreferences(0).getBoolean("music_map_bubble",false))return;a.frame.addView(new MusicMapBubble(a),new FrameLayout.LayoutParams(-2,-2));}
}
